// Represents config onboarding status on Global Manager.
type ConfigOnboardingStatus struct {
	Details *ConfigOnboardingStatusDetails
	// Site identifier of the site being onboarded.
	SiteId *string
	// Possible values are:
	//
	// * ConfigOnboardingStatus#ConfigOnboardingStatus_STATUS_ALLOWED
	// * ConfigOnboardingStatus#ConfigOnboardingStatus_STATUS_BLOCKED_FEATURE_CHECK
	// * ConfigOnboardingStatus#ConfigOnboardingStatus_STATUS_BLOCKED_CONFIG_CONFLICT_CHECK
	// * ConfigOnboardingStatus#ConfigOnboardingStatus_STATUS_BLOCKED_SITE_RESTORE_PENDING
	// * ConfigOnboardingStatus#ConfigOnboardingStatus_STATUS_BLOCKED_FULLSYNC_PENDING
	// * ConfigOnboardingStatus#ConfigOnboardingStatus_STATUS_BLOCKED_USER_REJECT
	// * ConfigOnboardingStatus#ConfigOnboardingStatus_STATUS_BLOCKED_SITE_NOT_REACHABLE
	// * ConfigOnboardingStatus#ConfigOnboardingStatus_STATUS_CONTINUE_RESOLUTION_NEEDED
	// * ConfigOnboardingStatus#ConfigOnboardingStatus_STATUS_IN_PROGRESS
	// * ConfigOnboardingStatus#ConfigOnboardingStatus_STATUS_FAILED_GM_ROLLBACK_IN_PROGRESS
	// * ConfigOnboardingStatus#ConfigOnboardingStatus_STATUS_SUCCESS
	//
	//  Onboarding Status
	Status *string
	// List of supported features on global manager.
	SupportedFeatures []OnboardingFeatureInfo
	// Onboarding status as of current timestamp. format: int64
	Timestamp *int64
	// List of unsupported features on global manager.
	UnsupportedFeatures []OnboardingFeatureInfo
}

